from html.parser import HTMLParser
class Validator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.errors = []
        self.tag_stack = []
    def handle_starttag(self, tag, attrs):
        if tag not in ['br', 'hr', 'img', 'input', 'meta', 'link', 'area', 'base', 'col', 'embed', 'param', 'source', 'track', 'wbr']:
            self.tag_stack.append(tag)
    def handle_endtag(self, tag):
        if tag not in ['br', 'hr', 'img', 'input', 'meta', 'link', 'area', 'base', 'col', 'embed', 'param', 'source', 'track', 'wbr']:
            if self.tag_stack and self.tag_stack[-1] == tag:
                self.tag_stack.pop()
            elif tag in self.tag_stack:
                self.errors.append(f'Mismatched tag: {tag}')

with open('/app/output/final_report.html', 'r') as f:
    html = f.read()
v = Validator()
v.feed(html)
print(f'HTML length: {len(html)} bytes')
print(f'Parse errors: {len(v.errors)}')
print('Report validation: PASSED' if len(v.errors) == 0 else f'Errors: {v.errors[:5]}')
"

